    """Decorator for transaction functions with extra control over the transaction."""
    def decorator(func):
        @wraps(func)
        def wrapper(tx, *args, **kwargs):
            tx.metadata = metadata if metadata is not None else {}
            tx.timeout = timeout
            return func(tx, *args, **kwargs)
        return wrapper
    return decorator
