def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    cache = {}
    queue = []

    def decorator(f):
        def wrapped(*args, **kwargs):
            if not typed:
                key = repr((args, sorted(kwargs.items())))
            else:
                key = repr(args) + repr(kwargs)

            # Get the result from the cache if available, otherwise fetch it
            if key in cache:
                result = cache[key]
            else:
                result = f(*args, **kwargs)
                cache[key] = result

            # Add the key to the MRU queue
            if key not in queue:
                queue.append(key)

            # If we are over the maxsize limit, remove items from the queue
            # and discard the associated cache entries
            if len(queue) > maxsize:
                key = queue.pop(0)
                del cache[key]

            return result
        return wrapped
    return decorator
