def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """

    if not orderings:
        return []

    def merge(orderings):
        # check if the current object is in any of the other orderings
        # if it is, return the merged orderings
        # else, return the current ordering
        if len(orderings) == 1:
            return orderings[0]
        else:
            for i in range(len(orderings)):
                for j in range(len(orderings)):
                    if orderings[i][0] in orderings[j]:
                        return merge([orderings[i] + orderings[j][1:], orderings[j]])
            # if the current ordering is not in any of the other orderings, return it
            return [orderings[0]]

    # recursive call to mergeOrderings with the merged orderings
    return merge(orderings)

