def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expressions
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for arg in args:
        if isinstance(arg, Expression):
            term = arg.term
            if not isinstance(term, Expression):
                result.append(arg)
                continue
            if term.operator == '|':
                if term.operands[0] == arg:
                    result.append(arg)
            elif term.operator == '&':
                if term.operands[1] == arg:
                    result.append(arg)
        elif isinstance(arg, Collection):
            result.extend(arg.absorb(self, args))
        else:
            result.append(arg)
    return result
