import subprocess  # Import the subprocess module

def run_command(command, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    cmd = [command] + args # Construct the command to run
    if cwd is not None:
        cwd = os.path.expanduser(cwd) # Expand any user directory references in cwd
    if env:
        env = env.copy() # Make a copy of the env dictionary
    else:
        env = {} # Create an empty dictionary
    env.update(os.environ) # Add environment variables from the current process

    # Run the command and get the output
    if not verbose:
        # Suppress stderr if verbose is False
        stderr = subprocess.DEVNULL
    elif hide_stderr:
        # Suppress stderr if hide_stderr is True
        stderr = subprocess.STDOUT
    else:
        # Print stderr if neither option is selected
        stderr = None
    try:
        output = subprocess.check_output(cmd, cwd=cwd, env=env, stderr=stderr)
    except subprocess.CalledProcessError as e:
        # The command returned a non-zero exit code
        raise RuntimeError("Error executing command") from e
    return output.decode("utf-8") # Decode the output and return it
