def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # json format
    try:
        return json.loads(document)
    except json.JSONDecodeError:
        pass

    # XRD format
    root = ET.fromstring(document)
    if root.tag != "{http://docs.oasis-open.org/ns/xri/xrd-1.0}XRD":
        raise ValueError("Invalid XRD format")
    result = {}
    for link in root.findall(".//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link"):
        for attributes in link.iter("{http://docs.oasis-open.org/ns/xri/xrd-1.0}*[@rel='http://joinmy.diaspora.git-partners.org/server_manifest']"):
            result["server_manifest"] = attributes.get("href")
            break
        for attributes in link.iter("{http://docs.oasis-open.org/ns/xri/xrd-1.0}*[@rel='http://joinmy.diaspora.git-partners.org/stream']"):
            result["stream"] = attributes.get("href")
            break
        # add more attributes as necessary
    else:
        raise ValueError("Invalid XRD format")

    return result
